    JOIN fans f ON i.interact_fan_pivot = f.user_registry
    JOIN membershipandspending m ON f.user_registry = m.member_fan_pivot
    WHERE f.status_tag = 'Inactive'
      AND m.memb_kind = 'Basic'
);

-- Drop all FK constraints that could prevent deletion
ALTER TABLE engagement DROP CONSTRAINT fk_engage_activity;
ALTER TABLE moderationandcompliance DROP CONSTRAINT fk_mod_interact;
ALTER TABLE supportandfeedback DROP CONSTRAINT fk_support_interact;
ALTER TABLE commerceandcollection DROP CONSTRAINT fk_commerce_engage;
ALTER TABLE loyaltyandachievements DROP CONSTRAINT fk_loyalty_engage;
ALTER TABLE retentionandinfluence DROP CONSTRAINT fk_retain_engage;
ALTER TABLE socialcommunity DROP CONSTRAINT fk_social_engage;

-- Get the engage_reg values that need to be deleted
WITH target_activities AS (
    SELECT i.activity_reg
    FROM interactions i
    JOIN fans f ON i.interact_fan_pivot = f.user_registry
    JOIN membershipandspending m ON f.user_registry = m.member_fan_pivot
    WHERE f.status_tag = 'Inactive' AND m.memb_kind = 'Basic'
),
target_engagements AS (
    SELECT DISTINCT e.engage_reg
    FROM engagement e
    WHERE e.engage_activity_pivot IN (SELECT activity_reg FROM target_activities)
)

-- Delete from commerceandcollection (depends on engagement)
DELETE FROM commerceandcollection
WHERE commerce_engage_pivot IN (SELECT engage_reg FROM target_engagements);

-- Delete from loyaltyandachievements (depends on engagement)
DELETE FROM loyaltyandachievements
WHERE loyalty_engage_pivot IN (SELECT engage_reg FROM target_engagements);

