DELETE FROM retentionandinfluence
WHERE retain_engage_pivot IN (SELECT engage_reg FROM target_engagements);

-- Delete from socialcommunity (depends on engagement)
DELETE FROM socialcommunity
WHERE social_engage_pivot IN (SELECT engage_reg FROM target_engagements);

